B.Qb=new A.eb("artifact_1","Tr\u1ed1ng \u0111\u1ed3ng \u0110\xf4ng S\u01a1n","Kh\u1ea3o c\u1ed5","museum_national","assets/images/ngoc-lu-web.jpg",B.by,"V\u0103n h\xf3a \u0110\xf4ng S\u01a1n","Ph\xf2ng tr\u01b0ng b\xe0y 2","Ti\u1ebfng v\u1ecdng c\u1ee7a m\u1ed9t n\u1ec1n v\u0103n minh. Tr\u1ed1ng \u0111\u1ed3ng k\u1ec3 c\xe2u chuy\u1ec7n v\u1ec1 \u0111\u1eddi s\u1ed1ng, t\xedn ng\u01b0\u1ee1ng v\xe0 t\xe0i ngh\u1ec7 \u0111\xfac \u0111\u1ed3ng c\u1ee7a c\u01b0 d\xe2n Vi\u1ec7t c\u1ed5.","\u1ede trung t\xe2m m\u1eb7t tr\u1ed1ng l\xe0 h\xecnh ng\xf4i sao nhi\u1ec1u c\xe1nh. Bao quanh l\xe0 c\xe1c v\xe0nh hoa v\u0103n h\xecnh h\u1ecdc, h\xecnh chim v\xe0 nh\u1eefng c\u1ea3nh sinh ho\u1ea1t c\u1ed9ng \u0111\u1ed3ng.\n\nKh\xf4ng ch\u1ec9 l\xe0 m\u1ed9t nh\u1ea1c kh\xed, tr\u1ed1ng \u0111\u1ed3ng c\xf2n g\u1eafn v\u1edbi nghi l\u1ec5 v\xe0 bi\u1ec3u tr\u01b0ng cho v\u1ecb th\u1ebf trong c\u1ed9ng \u0111\u1ed3ng. M\u1ed7i hoa v\u0103n l\xe0 m\u1ed9t d\u1ea5u v\u1ebft gi\xfap ch\xfang ta t\xecm hi\u1ec3u th\u1ebf gi\u1edbi c\u1ee7a c\u01b0 d\xe2n \u0110\xf4ng S\u01a1n.","H\xe3y quan s\xe1t t\u1eeb ng\xf4i sao gi\u1eefa m\u1eb7t tr\u1ed1ng ra c\xe1c v\xf2ng hoa v\u0103n b\xean ngo\xe0i. Nh\u1eefng h\xecnh ng\u01b0\u1eddi, chim v\xe0 ho\u1ea1t \u0111\u1ed9ng sinh ho\u1ea1t ph\u1ea3n \xe1nh m\u1ed1i li\xean h\u1ec7 gi\u1eefa con ng\u01b0\u1eddi v\u1edbi thi\xean nhi\xean trong v\u0103n h\xf3a \u0110\xf4ng S\u01a1n.","Tr\u1ed1ng \u0111\u1ed3ng n\xe0y g\u1eafn v\u1edbi n\u1ec1n v\u0103n h\xf3a n\xe0o?","Di s\u1ea3n Vi\u1ec7t c\u1ed5","assets/models/trong_dong_dong_son.glb")
B.Qd=new A.eb("artifact_2","\u1ea4n tri\u1ec7n ho\xe0ng cung","Cung \u0111\xecnh","museum_national","",B.by,"Tri\u1ec1u Nguy\u1ec5n","Ph\xf2ng tr\u01b0ng b\xe0y 7","M\u1ed9t d\u1ea5u \u1ea5n c\u1ee7a v\u01b0\u01a1ng tri\u1ec1u, g\u1eafn v\u1edbi v\u0103n th\u01b0 v\xe0 quy\u1ec1n l\u1ef1c trong \u0111\u1eddi s\u1ed1ng cung \u0111\xecnh.","\u1ea4n tri\u1ec7n \u0111\u01b0\u1ee3c s\u1eed d\u1ee5ng \u0111\u1ec3 x\xe1c nh\u1eadn v\u0103n b\u1ea3n v\xe0 th\u1ec3 hi\u1ec7n th\u1ea9m quy\u1ec1n. H\xecnh th\u1ee9c, ch\u1ea5t li\u1ec7u v\xe0 ch\u1eef kh\u1eafc tr\xean \u1ea5n ph\u1ea3n \xe1nh ch\u1ee9c n\u0103ng c\u1ee7a t\u1eebng lo\u1ea1i \u1ea5n trong h\u1ec7 th\u1ed1ng qu\u1ea3n l\xfd.\n\nQua hi\u1ec7n v\u1eadt n\xe0y, ng\u01b0\u1eddi xem c\xf3 th\u1ec3 t\xecm hi\u1ec3u m\u1ed1i li\xean h\u1ec7 gi\u1eefa ngh\u1ec7 thu\u1eadt ch\u1ebf t\xe1c, nghi l\u1ec5 v\xe0 ho\u1ea1t \u0111\u1ed9ng h\xe0nh ch\xednh c\u1ee7a tri\u1ec1u \u0111\xecnh.","\u1ea4n tri\u1ec7n gi\xfap x\xe1c nh\u1eadn th\u1ea9m quy\u1ec1n c\u1ee7a v\u0103n b\u1ea3n. Nh\u1eefng chi ti\u1ebft trang tr\xed cho th\u1ea5y \u0111\u1ed3 d\xf9ng h\xe0nh ch\xednh c\u0169ng mang gi\xe1 tr\u1ecb ngh\u1ec7 thu\u1eadt v\xe0 \xfd ngh\u0129a bi\u1ec3u t\u01b0\u1ee3ng.","\u1ea4n tri\u1ec7n n\xe0y \u0111\u01b0\u1ee3c gi\u1edbi thi\u1ec7u trong b\u1ed1i c\u1ea3nh tri\u1ec1u \u0111\u1ea1i n\xe0o?","D\u1ea5u \u1ea5n v\u01b0\u01a1ng tri\u1ec1u",null)
B.Qc=new A.eb("artifact_3","Trang b\xe1o c\xe1ch m\u1ea1ng","T\u01b0 li\u1ec7u","museum_ho_chi_minh","",B.by,"Th\u1ebf k\u1ef7 XX","Ph\xf2ng tr\u01b0ng b\xe0y 4","Nh\u1eefng con ch\u1eef l\u01b0u gi\u1eef kh\xe1t v\u1ecdng \u0111\u1ed9c l\u1eadp v\xe0 ti\u1ebfng n\xf3i c\u1ee7a m\u1ed9t th\u1eddi \u0111\u1ea1i.","B\xe1o ch\xed l\xe0 ph\u01b0\u01a1ng ti\u1ec7n truy\u1ec1n t\u1ea3i th\xf4ng tin, k\u1ebft n\u1ed1i c\u1ed9ng \u0111\u1ed3ng v\xe0 lan t\u1ecfa t\u01b0 t\u01b0\u1edfng. Nh\u1eefng trang b\xe1o c\xf2n l\u01b0u gi\u1eef c\xe1ch di\u1ec5n \u0111\u1ea1t, h\xecnh \u1ea3nh v\xe0 m\u1ed1i quan t\xe2m c\u1ee7a x\xe3 h\u1ed9i trong t\u1eebng giai \u0111o\u1ea1n.\n\n\u0110\u1ecdc l\u1ea1i m\u1ed9t trang b\xe1o l\xe0 m\u1ed9t c\xe1ch ti\u1ebfp c\u1eadn l\u1ecbch s\u1eed t\u1eeb nh\u1eefng \u0111i\u1ec1u ng\u01b0\u1eddi \u0111\u01b0\u01a1ng th\u1eddi \u0111\xe3 vi\u1ebft v\xe0 chia s\u1ebb.","H\xe3y ch\xfa \xfd c\xe1ch s\u1eafp x\u1ebfp ti\xeau \u0111\u1ec1 v\xe0 c\xe1c c\u1ed9t ch\u1eef. Trang b\xe1o l\xe0 ngu\u1ed3n t\u01b0 li\u1ec7u \u0111\u1ec3 t\xecm hi\u1ec3u vai tr\xf2 c\u1ee7a th\xf4ng tin trong vi\u1ec7c k\u1ebft n\u1ed1i c\u1ed9ng \u0111\u1ed3ng.","Trang b\xe1o \u0111\u01b0\u1ee3c gi\u1edbi thi\u1ec7u thu\u1ed9c giai \u0111o\u1ea1n n\xe0o?","K\xfd \u1ee9c th\u1ebf k\u1ef7 XX",null)
